-- 48 The Forge: strike, pump, quench. What it is about is felt: every blow
-- kicks the pad's strong motor (Input.rumble), harder the hotter the iron,
-- or buzzes a phone (Input.vibrate); the bellows hum in the weak one and a
-- quench hisses. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/48-the-forge.scene"
local RAISED, DOWN = 0.35, 1.6
local captions = true
local hammer, bar, bar_light, flash, sparks, steam, flames, embers, forge_light, bellows, status
local heat = 1
local swing, swing_t = nil, 0
local flash_i = 0
local t = 0
local was = {}

local function pad_down(i)
    return Input.is_gamepad_connected(0) and Input.is_gamepad_button_pressed(0, i)
end

local function pad_tap(i)
    local now = pad_down(i)
    local edge = now and not was[i]
    was[i] = now
    return edge
end

function init(entity)
    hammer = Entity.find_by_name("Hammer")
    bar = Entity.find_by_name("Bar")
    bar_light = Entity.find_by_name("BarLight")
    flash = Entity.find_by_name("Flash")
    sparks = Entity.find_by_name("Sparks")
    steam = Entity.find_by_name("Steam")
    flames = Entity.find_by_name("Flames")
    embers = Entity.find_by_name("Embers")
    forge_light = Entity.find_by_name("ForgeLight")
    bellows = Entity.find_by_name("Bellows")
    status = Entity.find_by_name("Status")
end

local function lerp(a, b, k) return a + (b - a) * k end

-- Iron by its heat: grey cold, dark red, orange, then yellow-white.
local function iron_colour(h)
    if h < 0.15 then return 0.06, 0.06, 0.07 end
    if h < 0.45 then local k = (h - 0.15) / 0.3; return lerp(0.06, 0.9, k), lerp(0.06, 0.08, k), lerp(0.07, 0.02, k) end
    if h < 0.75 then local k = (h - 0.45) / 0.3; return lerp(0.9, 2.2, k), lerp(0.08, 0.6, k), lerp(0.02, 0.08, k) end
    local k = (h - 0.75) / 0.25
    return lerp(2.2, 3.2, k), lerp(0.6, 2.6, k), lerp(0.08, 1.4, k)
end

local function strike()
    local s = 0.3 + 0.7 * heat
    Particles.emit_burst(sparks, math.floor(10 + 60 * heat * heat))
    flash_i = 3.5 * s
    Camera.shake(5 + 9 * s, 0.25, 0)
    Input.rumble(0, s, 0.4 * s, 0.16 + 0.1 * s)
    Input.vibrate(0.04 + 0.08 * s, s)
    Audio.play_sound("sounds/forge_clang.wav", 0.35 + 0.65 * s, 0.9 + 0.2 * heat)
    heat = math.max(0, heat - 0.05)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    t = t + dt

    -- The hammer: down fast, the blow at the bottom, up slower.
    if swing == nil and (Input.is_key_just_pressed("Space") or pad_tap(0)) then swing, swing_t = "down", 0 end
    local rot = RAISED
    if swing == "down" then
        swing_t = swing_t + dt
        local k = math.min(1, swing_t / 0.09)
        rot = lerp(RAISED, DOWN, k * k)
        if k >= 1 then strike(); swing, swing_t = "up", 0 end
    elseif swing == "up" then
        swing_t = swing_t + dt
        local k = math.min(1, swing_t / 0.28)
        rot = lerp(DOWN, RAISED, 1 - (1 - k) * (1 - k))
        if k >= 1 then swing = nil end
    end
    if hammer then Transform.set_rotation(hammer, rot) end

    -- The bellows: the fire roars, the iron heats, a low hum.
    local pumping = Input.is_key_pressed("B") or pad_down(2)
    if pumping then
        heat = math.min(1, heat + dt * 0.3)
        Input.rumble(0, 0.12, 0.08, 0.1)
        if not was.bellows then Audio.play_sound("sounds/forge_bellows.wav", 0.7) end
    end
    was.bellows = pumping
    if bellows then
        local squash = pumping and (0.75 + 0.25 * math.abs(math.cos(t * 6))) or 1
        Transform.set_scale(bellows, -1, squash)
    end
    if flames then Particles.set(flames, "emission_rate", pumping and 70 or 28) end
    if embers then Particles.set(embers, "emission_rate", pumping and 20 or 6) end

    -- Quench: all the heat at once, in steam and a long hiss.
    if (Input.is_key_just_pressed("Q") or pad_tap(1)) and heat > 0.05 then
        Particles.emit_burst(steam, math.floor(20 + 60 * heat))
        Audio.play_sound("sounds/forge_hiss.wav", 0.4 + 0.6 * heat)
        Input.rumble(0, 0.05, 0.5 * heat + 0.1, 0.9)
        Input.vibrate(0.5, 0.4)
        heat = 0
    end

    heat = math.max(0, heat - dt * 0.02)
    local r, g, b = iron_colour(heat)
    if bar then Sprite.set_color(bar, r, g, b, 1) end
    if bar_light then Lighting.set_intensity(bar_light, 1.6 * heat * heat) end
    flash_i = math.max(0, flash_i - dt * 14)
    if flash then Lighting.set_intensity(flash, flash_i) end
    if forge_light then
        local f = 0.85 + 0.1 * math.sin(t * 9.1) + 0.05 * math.sin(t * 23.7)
        Lighting.set_intensity(forge_light, (pumping and 2.4 or 1.8) * f)
    end
    if status then
        local pad = Input.is_gamepad_connected(0) and "pad 0 rumbles" or "no pad - a phone buzzes instead"
        UI.set_text(status, "heat " .. math.floor(heat * 100 + 0.5) .. "%   -   " .. pad)
    end
end
